function setup() {
	createCanvas(600, 600);
	background("beige")
	rectModenoStroke()
}

function draw() {
	translate(width/2, height/2)
	const num = 2;
	const S = width/(num*2+1);
	for (let y = -num; y <= num; y++) {		
		for (let x = -num; x <= num; x++) {
			fill(random(["orange", "grey", "darkred", "black"]))
			// fill(32)
			const tpe = ~~random(3)
			if (tpe === 0) circle(x*S, y*S, S)
			if (tpe === 1) rect(x*S, y*S, S)
			// if (t === 2) triangle(x*S, y*S, S)
			// console.log(tpe)
		}
	}
	// noLoop() removed for animation
}
